function get_site_option($k,$d=false){return $d;}function wc_get_order_statuses(){return ['wc-processing'=>'Processing'];}function get_posts($q){return $GLOBALS['existing_assigned']??[];}function get_option($k,$d=false){return $GLOBALS['options'][$k]??$d;}function add_option($k,$v,$x='',$a=false){if(isset($GLOBALS['options'][$k]))return false;$GLOBALS['options'][$k]=$v;return true;}function update_option($k,$v,$a=false){$GLOBALS['options'][$k]=$v;}function delete_option($k){unset($GLOBALS['options'][$k]);}function add_filter(...$a){$GLOBALS['hooks'][]=$a;}function add_action(...$a){}function sanitize_text_field($v){return trim(strip_tags((string)$v));}function wp_generate_uuid4(){return bin2hex(random_bytes(16));}function wp_date($f){return date($f);}function wc_get_order($id){return $GLOBALS['orders'][$id]??null;}function wc_get_logger(){return new class{function error($m,$c){$GLOBALS['error']=$m;}};}function wp_delete_file($p){unlink($p);}
