class Alkamy_Local_Pdf{static $renders=0;static function record($o,$t){return ['number'=>$o->get_meta('_alkamy_number_invoice')];}static function render($r){self::$renders++;return '%PDF-'.$r['number'];}}
require dirname(__DIR__).'/modules/invoicing/includes/class-alkamy-invoice-delivery.php';
function check($v,$m){if(!$v)throw new Exception($m);echo "PASS $m\n";}
$o=new WC_Order(101);$a=Alkamy_Invoice_Delivery::issue($o);check($a['number']!==''&&Alkamy_Local_Pdf::$renders===1,'First issue assigns number and renders');
$b=Alkamy_Invoice_Delivery::issue($o);check($a===$b&&Alkamy_Local_Pdf::$renders===1,'Resend reuses immutable archived bytes');
$o2=new WC_Order(102);$b=Alkamy_Invoice_Delivery::issue($o2);check($b['number']!==$a['number'],'Atomic number claims prevent reuse');
$o3=new WC_Order(103);$c=Alkamy_Invoice_Delivery::import_legacy($o3,'202610-000009','%PDF-original','wpc','2026-10-01');check(Alkamy_Invoice_Delivery::bytes(103)==='%PDF-original'&&$c['created']==='2026-10-01','Legacy import preserves exact bytes and date');
try{Alkamy_Invoice_Delivery::import_legacy(new WC_Order(104),'202610-000009','%PDF-different');throw new Exception('Duplicate allowed');}catch(RuntimeException $e){check(true,'Duplicate legacy invoice number rejected');}
check(Alkamy_Invoice_Delivery::attachments(['existing.pdf'],'customer_processing_order',$o)===['existing.pdf'],'Disabled delivery preserves other attachments');
update_option('alkamy_invoice_delivery',['enabled'=>true]);$paths=Alkamy_Invoice_Delivery::attachments(['existing.pdf'],'customer_processing_order',$o);check(count($paths)===2&&file_get_contents($paths[1])===Alkamy_Invoice_Delivery::bytes(101),'Enabled delivery appends real private PDF');
check(Alkamy_Invoice_Delivery::attachments($paths,'customer_processing_order',$o)===$paths,'Repeated filter invocation does not duplicate attachment');
check(Alkamy_Invoice_Delivery::attachments([],'new_order',$o)===[],'Admin email does not receive customer invoice');
Alkamy_Invoice_Delivery::cleanup();check(!file_exists($paths[1]),'Temporary attachment survives filter and is removed at shutdown cleanup');
$o4=new WC_Order(105);$o4->update_meta_data('_alkamy_number_invoice','MANUAL-001');$d=Alkamy_Invoice_Delivery::issue($o4);check($d['number']==='MANUAL-001','Merchant assigned number is preserved');

update_option('active_plugins',['wpc-pdf-invoices-premium/wpc-pdf-invoices.php']);check(Alkamy_Invoice_Delivery::attachments([],'customer_processing_order',$o)===[],'Active WPC prevents duplicate invoice attachments');update_option('active_plugins',[]);
$GLOBALS['options']['alkamy_invoice_lock_106']=time();try{Alkamy_Invoice_Delivery::issue(new WC_Order(106));throw new Exception('Concurrent issue allowed');}catch(RuntimeException $e){check(!Alkamy_Invoice_Delivery::get_issued(106),'Concurrent order issuance fails closed');}
$bad=new WC_Order(107);try{Alkamy_Invoice_Delivery::import_legacy($bad,'BAD','not-pdf');throw new Exception('Invalid PDF allowed');}catch(InvalidArgumentException $e){check(!Alkamy_Invoice_Delivery::get_issued(107),'Invalid import is never archived');}
$issued=$GLOBALS['options']['alkamy_issued_invoice_101'];$GLOBALS['options']['alkamy_issued_invoice_101']['pdf']=base64_encode('%PDF-corrupt');try{Alkamy_Invoice_Delivery::bytes(101);throw new Exception('Corruption allowed');}catch(RuntimeException $e){check(true,'Archive integrity failure blocks resend');}$GLOBALS['options']['alkamy_issued_invoice_101']=$issued;

$retry=new WC_Order(108);$GLOBALS['options']['alkamy_invoice_reservation_108']='RESERVED-108';$retryIssued=Alkamy_Invoice_Delivery::issue($retry);check($retryIssued['number']==='RESERVED-108','Retry reuses durable reservation even when order meta save was interrupted');
$GLOBALS['options']=[];$legacy=new WC_Order(160286);Alkamy_Invoice_Delivery::import_legacy($legacy,date('Ym').'-000001','%PDF-legacy','wpc','2026-10-05T14:49:55');$next=Alkamy_Invoice_Delivery::issue(new WC_Order(160287));check($next['number']===date('Ym').'-000002','Imported monthly ledger advances next invoice without reusing000001');check(Alkamy_Invoice_Delivery::get_issued(160286)['created']==='2026-10-05T14:49:55','Original ledger timestamp preserved');
try{Alkamy_Invoice_Delivery::atomic_add('unrelated_key','bad');throw new Exception('Unrelated key allowed');}catch(InvalidArgumentException $e){check(true,'Atomic option helper rejects unrelated keys');}
update_option('alkamy_invoice_delivery',['enabled'=>true,'email_ids'=>['new_order']]);check(Alkamy_Invoice_Delivery::attachments([],'new_order',$legacy)===[],'Configured admin email still cannot receive customer invoice');
